-- Arbeitsrecht Berufsbildung > Wirtschaftliche Zusammenhänge > Vor- Nachteile von Unternehmensformen > Flexibilität bei GbR
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Bietet die Flexibilität einer IT-GbR Vorteile bei der Entscheidungsfindung?', 2, '[{"text": "Ja", "correct": true, "because": "Gesellschafter entscheiden gemeinsam und flexibel"}, {"text": "Nein", "correct": false, "because": "Flexibilität ist ein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Können die Gesellschafter einer IT-GbR den Gesellschaftsvertrag frei gestalten?', 2, '[{"text": "Ja", "correct": true, "because": "GbR-Vertrag kann flexibel gestaltet werden"}, {"text": "Nein", "correct": false, "because": "Flexibilität im BGB vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Erhöht die Flexibilität einer IT-GbR die Abhängigkeit von Gesellschaftern?', 2, '[{"text": "Ja", "correct": true, "because": "Flexible Entscheidungen erfordern Einigkeit"}, {"text": "Nein", "correct": false, "because": "Abhängigkeit ist ein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Flexibilität einer IT-GbR ein Nachteil bei der Kapitalbeschaffung?', 2, '[{"text": "Nein", "correct": true, "because": "Flexibilität betrifft nicht direkt Kapital"}, {"text": "Ja", "correct": false, "because": "Kapital hängt von Gesellschaftern ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Flexibilität einer IT-GbR durch gesetzliche Vorgaben eingeschränkt werden?', 2, '[{"text": "Nein", "correct": true, "because": "BGB lässt große Freiheit bei der GbR"}, {"text": "Ja", "correct": false, "because": "Wenige gesetzliche Einschränkungen"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was bedeutet die Flexibilität einer IT-GbR?', 2, '[{"text": "Freie Gestaltung durch die Gesellschafter", "correct": true, "because": "GbR-Vertrag ist flexibel"}, {"text": "Strenge gesetzliche Vorgaben", "correct": false, "because": "Wenige Vorgaben"}, {"text": "Feste Geschäftsführung", "correct": false, "because": "Keine feste Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ergibt sich aus der Flexibilität einer IT-GbR?', 3, '[{"text": "Schnelle Entscheidungsfindung", "correct": true, "because": "Gesellschafter entscheiden direkt"}, {"text": "Hohe Kapitalaufnahme", "correct": false, "because": "Kapital nicht direkt betroffen"}, {"text": "Beschränkte Haftung", "correct": false, "because": "Haftung unbeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Nachteil kann durch die Flexibilität einer IT-GbR entstehen?', 3, '[{"text": "Abhängigkeit von der Einigkeit der Gesellschafter", "correct": true, "because": "Flexibilität erfordert Konsens"}, {"text": "Hohe Gründungskosten", "correct": false, "because": "Gründung ist kostengünstig"}, {"text": "Strenge Buchführung", "correct": false, "because": "Buchführung flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt die Flexibilität einer IT-GbR?', 2, '[{"text": "BGB", "correct": true, "because": "BGB (§§ 705 ff.) regelt die GbR"}, {"text": "HGB", "correct": false, "because": "Gilt für Handelsgesellschaften"}, {"text": "GmbHG", "correct": false, "because": "Gilt für GmbH"}]'),
('00000000-0000-0000-0000-000000000000', 'Warum ist die Flexibilität einer IT-GbR für kleine Teams vorteilhaft?', 3, '[{"text": "Schnelle Anpassung an Veränderungen", "correct": true, "because": "Kleine Teams entscheiden direkt"}, {"text": "Hohe Kapitalanforderung", "correct": false, "because": "Kein Mindestkapital"}, {"text": "Strenge Hierarchie", "correct": false, "because": "Keine feste Struktur"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Flexibilität einer IT-GbR?', 4, '[{"text": "Freie Gestaltung des Gesellschaftsvertrags", "correct": true, "because": "Gesellschafter bestimmen Regeln"}, {"text": "Schnelle Entscheidungsfindung", "correct": true, "because": "Keine festen Gremien"}, {"text": "Hohe Kapitalbeschaffung", "correct": false, "because": "Kapital von Gesellschaftern begrenzt"}, {"text": "Anpassungsfähigkeit an Projekte", "correct": true, "because": "Flexibel bei Änderungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile kann die Flexibilität einer IT-GbR mit sich bringen?', 3, '[{"text": "Abhängigkeit von Gesellschaftereinigkeit", "correct": true, "because": "Entscheidungen erfordern Konsens"}, {"text": "Fehlende formale Struktur", "correct": true, "because": "Keine festen Gremien"}, {"text": "Hohe Gründungskosten", "correct": false, "because": "Gründung ist kostengünstig"}, {"text": "Risiko von Konflikten", "correct": true, "because": "Flexibilität kann Streit fördern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussagen treffen auf die Flexibilität einer IT-GbR zu?', 4, '[{"text": "Gesellschafter entscheiden gemeinsam", "correct": true, "because": "Keine feste Geschäftsführung"}, {"text": "Vertrag frei gestaltbar", "correct": true, "because": "BGB lässt Spielraum"}, {"text": "Strenge gesetzliche Vorgaben", "correct": false, "because": "Wenige Vorgaben"}, {"text": "Hohe Anpassungsfähigkeit", "correct": true, "because": "Flexibel bei Änderungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren fördern die Flexibilität einer IT-GbR?', 3, '[{"text": "Wenige gesetzliche Vorgaben", "correct": true, "because": "BGB bietet Gestaltungsfreiheit"}, {"text": "Kleine Anzahl von Gesellschaftern", "correct": true, "because": "Kleine Teams entscheiden schneller"}, {"text": "Hohe Kapitalvorgaben", "correct": false, "because": "Kein Mindestkapital"}, {"text": "Direkte Entscheidungsbefugnis", "correct": true, "because": "Keine Gremien nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet die Flexibilität einer IT-GbR von der einer GmbH?', 3, '[{"text": "GbR hat weniger gesetzliche Vorgaben", "correct": true, "because": "GmbH strenger geregelt"}, {"text": "GmbH hat flexiblere Entscheidungsfindung", "correct": false, "because": "GmbH hat Geschäftsführer"}, {"text": "GbR ist einfacher anpassbar", "correct": true, "because": "Keine festen Strukturen"}, {"text": "GbR hat strengere Hierarchie", "correct": false, "because": "GbR hat keine Hierarchie"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Flexibilität einer IT-GbR ermöglicht schnelle Entscheidungen. b) Die Flexibilität führt zu hohen Gründungskosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schnelle Entscheidungen ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine IT-GbR kann den Gesellschaftsvertrag frei gestalten. b) Die Flexibilität der GbR fördert die Abhängigkeit von Gesellschaftern.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Freie Gestaltung und Abhängigkeit sind Merkmale"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Flexibilität einer IT-GbR ist ein Vorteil für kleine Teams. b) Die Flexibilität wird durch das GmbHG eingeschränkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kleine Teams ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Flexibilität einer IT-GbR ermöglicht Anpassung an Projekte. b) Die Flexibilität führt zu strengen Hierarchien.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anpassung ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Flexibilität einer IT-GbR ist ein Vorteil gegenüber der GmbH. b) Die Flexibilität der GbR erhöht die Kapitalbeschaffung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Flexibilität ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

